"""Shared responsive staff messenger for full-page inbox and floating staff window."""
from html import escape


def render_staff_messenger(csrf, selected=''):
    return '<div class="tr-staff-messenger" data-staff-messenger data-csrf="'+escape(csrf,quote=True)+'" data-selected="'+escape(str(selected),quote=True)+'"><aside class="tr-case-sidebar"><div class="tr-case-tabs"><button type="button" data-filter="open" aria-pressed="true">Active</button><button type="button" data-filter="finished" aria-pressed="false">Finished</button><button type="button" data-filter="archived" aria-pressed="false">Archived</button></div><p class="tr-case-summary">Loading conversations…</p><div class="tr-case-list" role="list" aria-label="Customer conversations"></div></aside><section class="tr-case-main"><header class="tr-case-heading"><button type="button" class="tr-case-back" aria-label="Back to conversation list">←</button><div><strong class="tr-case-title">Choose a conversation</strong><small class="tr-case-state"></small></div></header><div class="tr-case-log" role="log" aria-live="polite"><p>Select a customer on the left to read and reply.</p></div><div class="tr-case-actions"><button class="tr-button tr-case-older" type="button" hidden>Load earlier messages</button><button class="tr-button tr-case-finish" type="button" hidden>Finish Conversation</button><button class="tr-button tr-case-archive" type="button" hidden>Archive conversation</button></div><form class="tr-case-compose" hidden><label >Reply to customer<textarea name="body" maxlength="2000" placeholder="Reply to this customer…" required></textarea></label><button class="tr-button" type="submit">Send</button></form><p class="tr-case-notice" role="status"></p></section></div>'+STYLE+SCRIPT


STYLE = r'''<style>
.tr-staff-messenger{display:grid;grid-template-columns:280px minmax(0,1fr);height:650px;max-height:calc(100dvh - 170px);min-height:360px;border:1px solid #b2dfcd33;border-radius:18px;background:#17292f;overflow:hidden;color:#e4efea;font-size:13px}.tr-case-sidebar{display:flex;flex-direction:column;min-width:0;min-height:0;border-right:1px solid #ffffff18;background:#1d3036}.tr-case-tabs{display:flex;gap:4px;padding:12px 8px}.tr-case-tabs button{flex:1;min-width:0;padding:8px 3px;border:1px solid #ffffff20;background:transparent;border-radius:8px;font:inherit;color:#b8ceca;cursor:pointer}.tr-case-tabs button[aria-pressed=true]{background:#a8d8c42a;border-color:#a8d8c480;color:#d4f3e7}.tr-case-summary{padding:0 12px;font-size:11px;color:#aac0bd}.tr-case-list{overflow:auto;min-height:0;flex:1}.tr-case-item{display:block;text-align:left;width:100%;padding:15px 12px;border:0;border-top:1px solid #ffffff0d;background:transparent;color:#e4efea;cursor:pointer;font:inherit;min-width:0}.tr-case-item[aria-current=true]{background:#a8d8c41c;box-shadow:inset 3px 0 #a8d8c4}.tr-case-item-top{display:flex;gap:6px;align-items:center}.tr-case-item strong{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;min-width:0;flex:1}.tr-case-item p{margin:7px 0 0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:12px;color:#a8c0bd}.tr-case-main{display:flex;flex-direction:column;min-width:0;min-height:0}.tr-case-heading{display:flex;align-items:center;gap:10px;padding:15px;border-bottom:1px solid #ffffff18;min-height:60px;box-sizing:border-box}.tr-case-heading>div{min-width:0}.tr-case-title{display:block;overflow-wrap:anywhere}.tr-case-state{display:block;color:#a8c0bd;margin-top:3px}.tr-case-back{display:none;color:#d5ede4;background:transparent;border:1px solid #ffffff20;border-radius:8px;padding:8px}.tr-case-log{flex:1;min-height:0;overflow:auto;padding:16px;display:flex;flex-direction:column;gap:10px}.tr-case-bubble{padding:10px 13px;border-radius:12px;background:#ffffff08;max-width:86%;white-space:pre-wrap;overflow-wrap:anywhere;line-height:1.5}.tr-case-bubble.staff{align-self:flex-end;background:#436c5f80}.tr-case-bubble.customer{align-self:flex-start}.tr-case-bubble small{display:block;color:#b2cbc3;font-size:10px;margin-bottom:4px}.tr-case-actions{display:flex;gap:8px;padding:8px 12px;flex-wrap:wrap}.tr-case-actions .tr-button{font-size:11px;padding:8px 10px}.tr-case-compose{display:flex;gap:8px;padding:12px;border-top:1px solid #ffffff18;align-items:flex-end}.tr-case-compose label{flex:1;min-width:0;font-size:0}.tr-case-compose textarea{width:100%;height:66px;box-sizing:border-box;resize:vertical;font-size:13px;padding:10px}.tr-case-notice{padding:0 12px 10px;margin:0;font-size:11px;line-height:1.5;color:#c4dbd3}.tr-case-compose[hidden],.tr-case-actions button[hidden]{display:none!important}.tr-support-count{display:inline-flex;align-items:center;justify-content:center;min-width:21px;height:21px;padding:0 5px;box-sizing:border-box;border-radius:100px;background:#d84858;color:#fff;font-size:11px;font-weight:700;line-height:1;vertical-align:middle;margin-left:6px}.tr-support-count[hidden]{display:none!important}.tr-chat-box.tr-chat-staff{width:940px;height:650px;max-height:calc(100dvh - 110px)}.tr-chat-staff iframe{width:100%;height:100%;border:0;min-height:0;flex:1;background:#17292f}@media(max-width:680px){.tr-staff-messenger{grid-template-columns:1fr;max-height:calc(100dvh - 130px)}.tr-case-sidebar{border-right:0}.tr-case-main{display:none}.tr-staff-messenger.has-active .tr-case-sidebar{display:none}.tr-staff-messenger.has-active .tr-case-main{display:flex}.tr-case-back{display:block}.tr-case-bubble{max-width:92%}}
</style>'''

SCRIPT = r'''<script>(function(){document.querySelectorAll('[data-staff-messenger]').forEach(root=>{if(root.dataset.ready)return;root.dataset.ready='1';const list=root.querySelector('.tr-case-list'),log=root.querySelector('.tr-case-log'),form=root.querySelector('form'),field=form.elements.body,notice=root.querySelector('.tr-case-notice'),finish=root.querySelector('.tr-case-finish'),archive=root.querySelector('.tr-case-archive'),older=root.querySelector('.tr-case-older'),title=root.querySelector('.tr-case-title'),stateLabel=root.querySelector('.tr-case-state');let selected=root.dataset.selected||'',filter='open',lastId=0,state='',messages=new Map(),drafts=new Map(),pending=new Map(),busy=false,loading=false,version=0,paused=false;window.addEventListener('message',e=>{if(e.source===window.parent&&e.origin===location.origin){if(e.data&&e.data.type==='tr-chat-pause')paused=true;if(e.data&&e.data.type==='tr-chat-resume'){paused=false;loadInbox();loadThread()}}});
function report(text){notice.textContent=text||''}function count(value){window.dispatchEvent(new CustomEvent('tr-support-count',{detail:Number(value)||0}))}
async function api(url,options){const r=await fetch(url,Object.assign({credentials:'same-origin',cache:'no-store'},options));const data=await r.json();if(!r.ok)throw Error(data.error||'Chat could not be loaded.');return data}
function drawMessages(items,prepend){if(!prepend&&items.every(m=>messages.has(m.id)))return;const oldTop=log.scrollTop;const atBottom=log.scrollHeight-log.scrollTop-log.clientHeight<60,oldHeight=log.scrollHeight;items.forEach(m=>messages.set(m.id,m));const ordered=Array.from(messages.values()).sort((a,b)=>a.id-b.id);log.replaceChildren();ordered.forEach(m=>{const b=document.createElement('div');b.className='tr-case-bubble '+(m.sender==='staff'?'staff':'customer');const label=document.createElement('small');label.textContent=m.sender==='staff'?'TableRadar team':'Customer';b.append(label,document.createTextNode(m.body));log.append(b)});if(prepend)log.scrollTop=log.scrollHeight-oldHeight;else if(atBottom)log.scrollTop=log.scrollHeight;else log.scrollTop=oldTop}
async function loadThread(before){if(!selected)return;const id=selected,ticket=version;try{const data=await api('/staff/chat/'+encodeURIComponent(id)+'/messages'+(before?'?before='+Number(before):''));if(id!==selected||ticket!==version)return;state=data.state;title.textContent=data.email;stateLabel.textContent=state==='open'?'Active conversation':state==='finished'?'Finished · history saved':'Archived · history saved';drawMessages(data.messages,Boolean(before));lastId=Math.max(0,...messages.keys());if(before||!messages.size||Math.min(...messages.keys())>=Math.min(...data.messages.map(m=>m.id)))older.hidden=!data.has_older;finish.hidden=state!=='open';archive.hidden=state==='open'||state==='archived';form.hidden=state!=='open';form.querySelector('button').disabled=busy}catch(e){report(e.message)}}
async function loadInbox(){if(loading)return;loading=true;try{const data=await api('/staff/chat/inbox?state='+filter);count(data.waiting_count);root.querySelector('.tr-case-summary').textContent=data.waiting_count+' active conversations need a reply';list.replaceChildren();data.threads.forEach(t=>{const b=document.createElement('button');b.type='button';b.className='tr-case-item';b.setAttribute('aria-current',String(t.id===selected));const top=document.createElement('div');top.className='tr-case-item-top';const name=document.createElement('strong');name.textContent=t.email;top.append(name);if(t.state==='open'&&t.unanswered){const badge=document.createElement('span');badge.className='tr-support-count';badge.textContent=t.unanswered;badge.setAttribute('aria-label',t.unanswered+' unanswered messages');top.append(badge)}const preview=document.createElement('p');preview.textContent=t.preview;b.append(top,preview);b.addEventListener('click',()=>choose(t.id));list.append(b)});if(!data.threads.length)list.textContent='No conversations in this list.'}catch(e){report(e.message)}finally{loading=false}}
function choose(id){if(selected)drafts.set(selected,field.value);selected=id;version++;messages=new Map();log.replaceChildren();field.value=drafts.get(id)||'';root.classList.add('has-active');report('');loadThread();loadInbox()}
field.addEventListener('input',()=>{if(selected)drafts.set(selected,field.value)});root.querySelector('.tr-case-back').addEventListener('click',()=>root.classList.remove('has-active'));
root.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{filter=b.dataset.filter;root.querySelectorAll('[data-filter]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));loadInbox()}));
form.addEventListener('submit',async e=>{e.preventDefault();if(busy||!selected||state!=='open'||!field.value.trim())return;const id=selected,body=field.value;let job=pending.get(id);if(!job||job.body!==body)job={nonce:crypto.randomUUID(),body};pending.set(id,job);busy=true;form.querySelector('button').disabled=true;try{await api('/staff/chat/'+encodeURIComponent(id)+'/reply',{method:'POST',body:new URLSearchParams({csrf:root.dataset.csrf,body,nonce:job.nonce})});pending.delete(id);drafts.delete(id);if(selected===id&&field.value===body)field.value='';report('Reply sent.');await loadThread();await loadInbox()}catch(e){report(e.message)}finally{busy=false;form.querySelector('button').disabled=state!=='open'}});
finish.addEventListener('click',async()=>{if(!selected||busy||!confirm('Finish this conversation? Its history will be saved. The customer can open a new request.'))return;try{await api('/staff/chat/'+encodeURIComponent(selected)+'/finish',{method:'POST',body:new URLSearchParams({csrf:root.dataset.csrf,last_message_id:String(lastId)})});report('Conversation finished. History saved.');await loadThread();await loadInbox()}catch(e){report(e.message);loadThread()}});
archive.addEventListener('click',async()=>{if(!selected||busy)return;try{await api('/staff/chat/'+encodeURIComponent(selected)+'/archive',{method:'POST',body:new URLSearchParams({csrf:root.dataset.csrf})});report('Archived. History remains available in Archived and to the customer.');await loadThread();await loadInbox()}catch(e){report(e.message)}});
older.addEventListener('click',()=>{const ids=Array.from(messages.keys());if(ids.length)loadThread(Math.min(...ids))});loadInbox();if(selected)choose(selected);setInterval(()=>{if(paused||document.visibilityState==='hidden')return;loadInbox();loadThread()},7000)
})})();</script>'''
